def brief(value):
    text = repr(value)
    return text if len(text) <= 100 else text[:97] + "..."
def valid_order(n, prerequisites):
    """Call course_order and check its answer: every course exactly once, and every prerequisite before the course that needs it."""
    order = course_order(n, [list(pair) for pair in prerequisites])
    if not isinstance(order, list):
        raise AssertionError(f"expected a list with all {n} courses, got {brief(order)}")
    if sorted(order) != list(range(n)):
        raise AssertionError(f"the order must hold each course from 0 to {n - 1} exactly once, got {brief(order)}")
    position = {course: i for i, course in enumerate(order)}
    for course, needs in prerequisites:
        if position[needs] > position[course]:
            raise AssertionError(f"course {course} comes before its prerequisite {needs} in {brief(order)}")
    return True
